const acorn = require('acorn')
const escodegen = require('escodegen')
const { initializeVisualBinding, disposeVisualBinding } = require('./panel-binding-editor')
const { fetchWithTimeout } = require('./panel-http')
const { createTargetMatcher } = require('./control-type-model')
const { createRoomMeterReceiver, createMeterRenderer } = require('./meter-frame')
const { createPanelMeterClient } = require('./panel-meter-client')
const { createRoomXYSeriesReceiver, createXYSeriesRenderer } = require('./xy-series-frame')
const { createPanelXYSeriesClient } = require('./panel-xy-series-client')
const { attachMomentaryButton } = require('./panel-momentary-client')
const { attachButtonPress } = require('./panel-button-press')

const CONTROL_POLICY_MARKER = '/* ui-control-panel-control-api-v1 */'


function createControlPanelPolicy ({
  dispatch,
  intervalMs = 40,
  now = () => Date.now(),
  setTimer = setTimeout,
  clearTimer = clearTimeout,
  onError = () => {}
}) {
  if (typeof dispatch !== 'function') throw new Error('ControlPanel dispatch function is required')
  if (!Number.isFinite(intervalMs) || intervalMs < 0) throw new Error('ControlPanel interval must be a non-negative number')

  const continuousTypes = new Set(['level', 'dimmer', 'position'])
  const discreteTypes = new Set(['power', 'source', 'preset', 'mute', 'text'])
  const continuousControls = new Map()
  let discreteQueue = Promise.resolve()
  let disposed = false

  const reportError = (error, command) => {
    try {
      onError(error, command)
    } catch (_) {}
  }

  const normalize = (command) => {
    if (!command || typeof command !== 'object' || Array.isArray(command)) {
      throw new Error('Control command must be an object')
    }
    const type = String(command.type ?? command.controlType ?? '').trim().toLowerCase()
    const topic = String(command.topic ?? '').trim()
    const key = String(command.key ?? command.controlKey ?? '').trim()
    const hasValue = Object.prototype.hasOwnProperty.call(command, 'value') ||
      Object.prototype.hasOwnProperty.call(command, 'payload')

    if (!continuousTypes.has(type) && !discreteTypes.has(type)) {
      throw new Error('Unsupported control type: ' + type)
    }
    if (!topic) throw new Error('Control command needs a topic')
    if (!/^[a-zA-Z0-9._:/-]{1,160}$/.test(key)) throw new Error('Control command needs a valid key')
    if (!hasValue) throw new Error('Control command needs a value')

    return {
      topic,
      payload: Object.prototype.hasOwnProperty.call(command, 'value') ? command.value : command.payload,
      controlType: type,
      controlKey: key,
      final: command.final === true
    }
  }

  const continuousControl = (key) => {
    let control = continuousControls.get(key)
    if (!control) {
      control = {
        inFlight: false,
        lastCommand: null,
        lastSentAt: -intervalMs,
        latest: null,
        timer: null
      }
      continuousControls.set(key, control)
    }
    return control
  }

  const dispatchContinuous = async (key) => {
    const control = continuousControl(key)
    if (control.inFlight || !control.latest) return

    const command = control.latest
    control.latest = null
    control.inFlight = true
    try {
      await dispatch(command)
    } catch (error) {
      reportError(error, command)
    } finally {
      control.lastSentAt = now()
      control.inFlight = false
      if (!disposed && control.latest) scheduleContinuous(key, control.latest.final)
    }
  }

  const scheduleContinuous = (key, force) => {
    const control = continuousControl(key)
    if (control.inFlight || !control.latest) return
    if (force && control.timer) {
      clearTimer(control.timer)
      control.timer = null
    }
    if (control.timer) return

    const delay = force ? 0 : Math.max(0, intervalMs - (now() - control.lastSentAt))
    if (delay === 0) {
      void dispatchContinuous(key)
      return
    }
    control.timer = setTimer(() => {
      control.timer = null
      void dispatchContinuous(key)
    }, delay)
  }

  const sendDiscrete = (command) => {
    discreteQueue = discreteQueue
      .catch(() => undefined)
      .then(() => disposed ? undefined : dispatch(command))
      .catch((error) => reportError(error, command))
    return discreteQueue
  }

  return {
    send (command) {
      if (disposed) return Promise.resolve()
      const normalized = normalize(command)
      if (continuousTypes.has(normalized.controlType)) {
        const control = continuousControl(normalized.controlKey)
        control.lastCommand = normalized
        control.latest = normalized
        scheduleContinuous(normalized.controlKey, normalized.final)
        return Promise.resolve()
      }
      return sendDiscrete(normalized)
    },

    flush (key) {
      const control = continuousControls.get(String(key))
      if (disposed || !control || !control.lastCommand) return Promise.resolve()
      control.latest = { ...control.lastCommand, final: true }
      scheduleContinuous(control.latest.controlKey, true)
      return Promise.resolve()
    },

    dispose () {
      disposed = true
      for (const control of continuousControls.values()) {
        if (control.timer) clearTimer(control.timer)
        control.latest = null
      }
      continuousControls.clear()
    }
  }
}


// Dashboard 2.0 1.31 parses ui-template scripts itself. It only treats a script
// as component options when the script contains one `export default { ... }`
// statement. Keep every helper inside data, methods, or lifecycle hooks so the
// generated script remains inside that supported subset.
function buildDashboardPolicyOptionsSource (controls = [], boundPanel = null) {
  const boundControls = controls.map(({ id, type, mode }) => ({ id, type, mode }))
  const meterMethods = boundPanel?.meter
    ? `__createRoomMeterReceiver: ${createRoomMeterReceiver.toString()},
    __createMeterRenderer: ${createMeterRenderer.toString()},
    __createPanelMeterClient: ${createPanelMeterClient.toString()},`
    : ''
  const xySeriesMethods = boundPanel?.xySeries
    ? `__createXYSeriesReceiver: ${createRoomXYSeriesReceiver.toString()},
    __createXYSeriesRenderer: ${createXYSeriesRenderer.toString()},
    __createPanelXYSeriesClient: ${createPanelXYSeriesClient.toString()},`
    : ''
  const visualMethods = boundPanel?.visual
    ? `__createTargetMatcher: ${createTargetMatcher.toString()},
    __attachMomentaryButton: ${attachMomentaryButton.toString()},
    __attachButtonPress: ${attachButtonPress.toString()},
    __initializeVisualBinding: ${initializeVisualBinding.toString()},
    __disposeVisualBinding: ${disposeVisualBinding.toString()},`
    : ''
  const visualMounted = boundPanel?.visual
    ? 'this.$nextTick(() => this.__initializeVisualBinding())'
    : ''
  const visualUnmounted = boundPanel?.visual ? 'this.__disposeVisualBinding()' : ''
  return `
export default {
  data () {
    return {
      boundState: {},
      boundPending: {},
      boundTargets: {},
      boundUnconfirmed: {},
      boundFeedbackRevision: 0,
      boundFeedbackConnected: false,
      boundAvailability: {},
      boundAuthenticated: false,
    }
  },
  methods: {
    ${meterMethods}
    ${xySeriesMethods}
    ${visualMethods}
    __panelFetch: ${fetchWithTimeout.toString()},
    __boundPanelConfig () {
      return ${JSON.stringify(boundPanel)}
    },
    __boundControls () {
      return ${JSON.stringify(boundControls)}
    },
    __boundControl (id) {
      return this.__boundControls().find(control => control.id === id)
    },
    __deviceAvailable (id) {
      const binding = this.__boundPanelConfig()?.visual?.bindings?.[id]
      if (!binding?.readMeta?.availability?.online && !binding?.writeMeta?.availability?.online) return true
      return this.boundAvailability[id] === true
    },
    applyBoundFeedback (message) {
      if (['bound-snapshot', 'bound-feedback', 'bound-availability'].includes(message?.kind) &&
        message.room === this.__boundPanelConfig()?.room && Number.isInteger(message.revision) &&
        typeof message.feedbackEpoch === 'string' && message.feedbackEpoch !== this.__boundFeedbackEpoch &&
        (message.kind === 'bound-availability' ? Array.isArray(message.availability) : Array.isArray(message.items))) {
        this.__boundFeedbackEpoch = message.feedbackEpoch
        this.__resetControlPolicy?.()
        this.__clearAllBoundSettlements?.()
        this.boundState = {}
        this.boundAvailability = {}
        this.boundFeedbackRevision = 0
      }
      if (message?.kind === 'bound-availability') {
        if (message.room !== this.__boundPanelConfig()?.room || !Array.isArray(message.availability) ||
          !Number.isInteger(message.revision) || message.revision < this.boundFeedbackRevision) return false
        this.boundFeedbackRevision = message.revision
        this.boundAvailability = Object.fromEntries(message.availability.filter(item =>
          typeof item?.id === 'string' && typeof item.available === 'boolean').map(item => [item.id, item.available]))
        for (const [id, available] of Object.entries(this.boundAvailability)) if (!available) this.__clearBoundPending(id)
        return true
      }
      if (['bound-snapshot', 'bound-feedback'].includes(message?.kind)) {
        if (message.room !== this.__boundPanelConfig()?.room || !Array.isArray(message.items) ||
          !Number.isInteger(message.revision) || message.revision < this.boundFeedbackRevision) return false
        if (message.kind === 'bound-snapshot') {
          this.boundState = {}
          this.boundAvailability = Object.fromEntries((message.availability || []).map(item => [item.id, item.available === true]))
        }
        this.boundFeedbackRevision = message.revision
        return message.items.map(item => this.applyBoundFeedback({
          __boundRevision: message.revision,
          _controlPanel: { kind: 'state', id: item.id, value: item.value }
        }))
      }
      const state = message?._controlPanel
      if (state?.kind === 'states' && Array.isArray(state.items)) {
        return state.items.map(item => this.applyBoundFeedback({ _controlPanel: { kind: 'state', ...item } }))
      }
      if (state?.kind !== 'state' || !this.__boundControl(state.id) ||
        !Object.prototype.hasOwnProperty.call(state, 'value')) return false
      this.boundState = { ...this.boundState, [state.id]: state.value }
      const control = this.__boundControl(state.id)
      if (!['level', 'dimmer', 'position'].includes(control.type) ||
        Object.is(this.boundTargets[state.id], state.value)) {
        this.__clearBoundPending(state.id)
      } else {
        const settlement = this.__boundSettlements.get(state.id)
        if (settlement && (message.__boundRevision === undefined ||
          message.__boundRevision > settlement.finalRevision)) {
          settlement.newFeedback = true
          if (settlement.expired) this.__clearBoundPending(state.id)
        }
      }
      return true
    },
    __clearBoundPending (id) {
      const settlement = this.__boundSettlements.get(id)
      if (settlement?.timer) clearTimeout(settlement.timer)
      this.__boundSettlements.delete(id)
      const pending = { ...this.boundPending }
      const targets = { ...this.boundTargets }
      const unconfirmed = { ...this.boundUnconfirmed }
      delete pending[id]
      delete targets[id]
      delete unconfirmed[id]
      this.boundPending = pending
      this.boundTargets = targets
      this.boundUnconfirmed = unconfirmed
    },
    __clearAllBoundSettlements () {
      for (const settlement of this.__boundSettlements.values()) {
        if (settlement.timer) clearTimeout(settlement.timer)
      }
      this.__boundSettlements.clear()
      this.boundPending = {}
      this.boundTargets = {}
      this.boundUnconfirmed = {}
    },
    __boundSettleDelayMs () { return 700 },
    controlValue (id, fallback = null) {
      return Object.prototype.hasOwnProperty.call(this.boundState, id) ? this.boundState[id] : fallback
    },
    boundDisplayValue (id, fallback = null) {
      return this.boundPending[id] === true && Object.prototype.hasOwnProperty.call(this.boundTargets, id)
        ? this.boundTargets[id] : this.controlValue(id, fallback)
    },
    sendBoundControl (command) {
      const id = command?.id
      const control = this.__boundControl(id)
      if (!control) throw new Error('Unknown control ID: ' + id)
      if (control.mode === 'read') throw new Error('Read-only control: ' + id)
      if (!this.__deviceAvailable(id)) throw new Error('Device is unavailable')
      if (!Object.prototype.hasOwnProperty.call(command, 'value')) throw new Error('Bound control needs a value')
      if (!this.__boundPanelSession?.csrf) throw new Error('Bound panel login required')
      const previous = this.__boundSettlements.get(id)
      if (previous?.timer) clearTimeout(previous.timer)
      this.__boundSettlements.delete(id)
      const unconfirmed = { ...this.boundUnconfirmed }
      delete unconfirmed[id]
      this.boundUnconfirmed = unconfirmed
      this.boundPending = { ...this.boundPending, [id]: true }
      const continuous = ['level', 'dimmer', 'position'].includes(control.type)
      this.boundTargets = { ...this.boundTargets, [id]: command.value }
      try {
        const sent = this.__controlPanelPolicy.send({
          type: control.type, topic: '__bound', key: id,
          value: command.value, final: command.final === true
        })
        if (continuous && command.final === true) {
          const settlement = { finalRevision: this.boundFeedbackRevision, newFeedback: false, expired: false, timer: null }
          settlement.timer = setTimeout(() => {
            if (this.__boundSettlements.get(id) !== settlement) return
            settlement.timer = null
            settlement.expired = true
            if (settlement.newFeedback) this.__clearBoundPending(id)
            else this.boundUnconfirmed = { ...this.boundUnconfirmed, [id]: true }
          }, this.__boundSettleDelayMs())
          this.__boundSettlements.set(id, settlement)
        }
        return sent
      } catch (error) {
        this.__clearBoundPending(id)
        throw error
      }
    },
    __controlPanelCreatePolicy: ${createControlPanelPolicy.toString()},
    __initializeControlPanelPolicy () {
      this.__boundPanelSession = null
      this.__boundPanelSource = null
      this.__boundAuthGeneration = 0
      this.__boundSettlements = new Map()
      this.__resetControlPolicy()
      if (typeof this.$watch === 'function') {
        this.__boundUnwatch = this.$watch('msg', message => this.applyBoundFeedback(message), { immediate: true })
      }
    },
    __disposeControlPanelPolicy () {
      this.__boundAuthGeneration++
      this.__boundUnwatch?.()
      this.__boundUnwatch = null
      this.__clearAllBoundSettlements()
      this.__closeBoundFeedback()
      this.__controlPanelPolicy?.dispose()
      this.__controlPanelPolicy = null
      this.__boundPanelSession = null
    },
    __resetControlPolicy () {
      this.__controlPanelPolicy?.dispose()
      this.__controlPanelPolicy = this.__controlPanelCreatePolicy({
        intervalMs: 40,
        dispatch: (command) => this.__dispatchControl(command),
        onError: (error, command) => {
          if (command?.topic === '__bound' && command.controlKey) {
            this.__clearBoundPending(command.controlKey)
          }
          if (typeof this.onControlError === 'function') this.onControlError(error, command)
          else console.error('ControlPanel command failed', error)
        }
      })
    },
    __closeBoundFeedback () {
      this.__boundPanelSource?.close()
      this.__boundPanelSource = null
      this.boundFeedbackConnected = false
    },
    __connectBoundFeedback () {
      this.__closeBoundFeedback()
      const config = this.__boundPanelConfig()
      if (!config || !this.__boundPanelSession || typeof EventSource === 'undefined') return
      const source = new EventSource(config.endpoint + '/events')
      this.__boundPanelSource = source
      source.onopen = () => {
        if (this.__boundPanelSource === source) this.boundFeedbackConnected = true
      }
      source.onmessage = event => {
        if (this.__boundPanelSource !== source) return
        try { this.applyBoundFeedback(JSON.parse(event.data)) } catch (error) {
          if (typeof this.onControlError === 'function') this.onControlError(error)
          else console.error('Bound feedback failed', error)
        }
      }
      source.onerror = () => {
        if (this.__boundPanelSource === source) {
          this.boundFeedbackConnected = false
          this.__resetControlPolicy()
          this.__clearAllBoundSettlements()
        }
      }
    },
    setBoundPanelSession (session) {
      const config = this.__boundPanelConfig()
      if (!config || session?.room !== config.room || !session.csrf) {
        throw new Error('Invalid bound panel session')
      }
      if (this.__boundPanelSession?.csrf !== session.csrf ||
        (session.feedbackEpoch && session.feedbackEpoch !== this.__boundFeedbackEpoch)) {
        this.__resetControlPolicy()
        this.__clearAllBoundSettlements()
        this.boundState = {}
        this.boundFeedbackRevision = 0
      }
      this.__boundFeedbackEpoch = session.feedbackEpoch || null
      this.__boundPanelSession = { room: session.room, csrf: session.csrf, holdEpoch: session.holdEpoch,
        feedbackEpoch: session.feedbackEpoch }
      this.boundAuthenticated = true
      this.__connectBoundFeedback()
    },
    clearBoundPanelSession () {
      this.__boundAuthGeneration++
      this.__closeBoundFeedback()
      this.__boundPanelSession = null
      this.boundAuthenticated = false
      this.__resetControlPolicy()
      this.__clearAllBoundSettlements()
      this.boundState = {}
      this.boundFeedbackRevision = 0
    },
    async loginBoundPanel (username, password) {
      const config = this.__boundPanelConfig()
      if (!config) throw new Error('This panel has no bound login endpoint')
      this.clearBoundPanelSession()
      const generation = this.__boundAuthGeneration
      const { response, session } = await this.__panelFetch(config.endpoint + '/login', {
        method: 'POST', credentials: 'same-origin',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ username, password })
      }, 12000, async response => ({ response, session: response.ok ? await response.json() : null }))
      if (!response.ok) throw new Error('Panel login failed (' + response.status + ')')
      if (generation !== this.__boundAuthGeneration) return null
      this.setBoundPanelSession(session)
      return session
    },
    async restoreBoundPanelSession (timeoutMs = 12000) {
      const config = this.__boundPanelConfig()
      if (!config) return null
      const generation = this.__boundAuthGeneration
      const { response, session } = await this.__panelFetch(config.endpoint + '/session', {
        credentials: 'same-origin'
      }, timeoutMs, async response => ({ response, session: response.ok ? await response.json() : null }))
      if (generation !== this.__boundAuthGeneration) return this.__boundPanelSession
      if (!response.ok) {
        if (response.status === 401) {
          this.clearBoundPanelSession()
          return null
        }
        const error = new Error('Panel session unavailable (' + response.status + ')')
        error.status = response.status
        throw error
      }
      if (generation !== this.__boundAuthGeneration) return this.__boundPanelSession
      this.setBoundPanelSession(session)
      return session
    },
    async logoutBoundPanel () {
      const config = this.__boundPanelConfig()
      const session = this.__boundPanelSession
      this.clearBoundPanelSession()
      if (!config || !session) return
      const response = await this.__panelFetch(config.endpoint + '/logout', {
        method: 'POST', credentials: 'same-origin',
        headers: { 'Content-Type': 'application/json', 'X-Room-CSRF': session.csrf },
        body: '{}'
      })
      if (!response.ok) throw new Error('Panel logout failed (' + response.status + ')')
    },
    flushControl (key) {
      return this.__controlPanelPolicy.flush(key)
    },
    async __dispatchControl(command) {
      if (command.topic !== '__bound')
        throw new Error('Unsupported control command');
      const config = this.__boundPanelConfig();
      const session = this.__boundPanelSession;
      if (!config || !session)
        throw new Error('Bound panel login required');
      if (!this.__deviceAvailable(command.controlKey)) throw new Error('Device is unavailable');
      const response = await this.__panelFetch(config.endpoint + '/bound-command', {
        method: 'POST',
        credentials: 'same-origin',
        headers: {
          'Content-Type': 'application/json',
          'X-Room-CSRF': session.csrf
        },
        body: JSON.stringify({
          room: session.room,
          _controlPanel: {
            kind: 'command',
            id: command.controlKey,
            value: command.payload,
            final: command.final
          }
        }),
      }, 8000);
      if (!response.ok) {
        if (response.status === 401)
          this.clearBoundPanelSession();
        throw new Error('Bound command failed (' + response.status + ')');
      }
      return response;
    }
  },
  mounted () {
    this.__initializeControlPanelPolicy()
    ${boundPanel?.visual ? '' : 'if (this.__boundPanelConfig()) this.restoreBoundPanelSession().catch(() => undefined)'}
    ${visualMounted}
  },
  unmounted () {
    ${visualUnmounted}
    this.__disposeControlPanelPolicy()
  }
}
`
}

function parseOptionsObject (source) {
  const tree = acorn.parse(source, { ecmaVersion: 'latest', sourceType: 'module' })
  if (tree.body.length !== 1 || tree.body[0].type !== 'ExportDefaultDeclaration' ||
    tree.body[0].declaration.type !== 'ObjectExpression') return null
  return tree.body[0].declaration
}

function propertyName (property) {
  if (!property || property.type !== 'Property') return null
  if (!property.computed && property.key.type === 'Identifier') return property.key.name
  if (property.key.type === 'Literal') return String(property.key.value)
  return null
}

function findProperty (object, name) {
  return object.properties.find(property => propertyName(property) === name)
}

function parseProperty (source) {
  const object = acorn.parse('({' + source + '})', { ecmaVersion: 'latest' }).body[0].expression
  return object.properties[0]
}

function functionSource (property) {
  return property ? escodegen.generate(property.value) : null
}

function mergeDashboardOptions (userSource, controls = [], boundPanel = null) {
  const user = parseOptionsObject(userSource)
  if (!user) return null

  const policy = parseOptionsObject(buildDashboardPolicyOptionsSource(controls, boundPanel))
  const policyData = findProperty(policy, 'data')
  const policyMethods = findProperty(policy, 'methods')
  const policyMounted = findProperty(policy, 'mounted')
  const policyUnmounted = findProperty(policy, 'unmounted')
  const userData = findProperty(user, 'data')
  const userMethods = findProperty(user, 'methods')
  const userMounted = findProperty(user, 'mounted')
  const userUnmounted = findProperty(user, 'unmounted')

  if (userMethods && userMethods.value.type !== 'ObjectExpression') return null

  const data = userData
    ? parseProperty(`data () {
        const userState = (${functionSource(userData)}).call(this) || {}
        const policyState = (${functionSource(policyData)}).call(this) || {}
        return { ...userState, ...policyState }
      }`)
    : policyData

  const policyMethodNames = new Set(policyMethods.value.properties.map(propertyName))
  const methods = parseProperty('methods: {}')
  methods.value.properties = [
    ...(userMethods ? userMethods.value.properties.filter(property => !policyMethodNames.has(propertyName(property))) : []),
    ...policyMethods.value.properties
  ]

  const mounted = userMounted
    ? parseProperty(`mounted () {
        (${functionSource(policyMounted)}).call(this)
        return (${functionSource(userMounted)}).call(this)
      }`)
    : policyMounted

  const unmounted = userUnmounted
    ? parseProperty(`unmounted () {
        try {
          return (${functionSource(userUnmounted)}).call(this)
        } finally {
          (${functionSource(policyUnmounted)}).call(this)
        }
      }`)
    : policyUnmounted

  const replaced = new Set(['data', 'methods', 'mounted', 'unmounted'])
  const merged = {
    ...user,
    properties: [
      ...user.properties.filter(property => !replaced.has(propertyName(property))),
      data,
      methods,
      mounted,
      unmounted
    ]
  }

  return CONTROL_POLICY_MARKER + '\nexport default ' + escodegen.generate(merged, {
    format: { indent: { style: '  ' } }
  })
}

function injectControlPolicy (format, controls = [], boundPanel = null) {
  if (typeof format !== 'string' || format.includes(CONTROL_POLICY_MARKER)) return format

  const scriptMatch = /<script(?!\s+setup\b)(?:\s[^>]*)?>/i.exec(format)
  if (!scriptMatch) {
    const setupMatch = /<script\s+setup\b([^>]*)>/i.exec(format)
    if (setupMatch || !/<template(?:\s|>)/i.test(format)) return format
    return format + '\n<script>\n' + CONTROL_POLICY_MARKER + '\n' +
      buildDashboardPolicyOptionsSource(controls, boundPanel).trim() + '\n</script>\n'
  }

  const scriptStart = scriptMatch.index + scriptMatch[0].length
  const scriptEnd = format.indexOf('</script>', scriptStart)
  if (scriptEnd === -1) return format

  const source = format.slice(scriptStart, scriptEnd)
  let wrapped
  try {
    wrapped = mergeDashboardOptions(source, controls, boundPanel)
  } catch (_) {
    return format
  }
  if (!wrapped) return format
  return format.slice(0, scriptStart) + '\n' + wrapped + '\n' + format.slice(scriptEnd)
}

module.exports = {
  CONTROL_POLICY_MARKER,
  buildDashboardPolicyOptionsSource,
  createControlPanelPolicy,
  injectControlPolicy,
  mergeDashboardOptions,
}
